import{_ as o,o as a,c as t,a2 as d}from"./chunks/framework.CyZTVJbV.js";const u=JSON.parse('{"title":"kiwa v1.17 released — Observability v2 (dashboard + alert + trace flame graph + log correlation)","description":"","frontmatter":{},"headers":[],"relativePath":"announcements/v1.17/gh-discussions-announcement.md","filePath":"announcements/v1.17/gh-discussions-announcement.md"}'),r={name:"announcements/v1.17/gh-discussions-announcement.md"};function c(s,e,l,n,i,h){return a(),t("div",null,[...e[0]||(e[0]=[d('<h1 id="kiwa-v1-17-released-—-observability-v2-dashboard-alert-trace-flame-graph-log-correlation" tabindex="-1">kiwa v1.17 released — Observability v2 (dashboard + alert + trace flame graph + log correlation) <a class="header-anchor" href="#kiwa-v1-17-released-—-observability-v2-dashboard-alert-trace-flame-graph-log-correlation" aria-label="Permalink to &quot;kiwa v1.17 released — Observability v2 (dashboard + alert + trace flame graph + log correlation)&quot;">​</a></h1><p>v1.17 is out. After v1.16&#39;s component test vertical (<code>@kiwa/component</code> v0.1 unifying Storybook 8 + Playwright CT + Chromatic), v1.17 turns to the <strong>SaaS observability stack</strong> every production team already ships: Grafana-style dashboards, Prometheus AlertManager-style routing, trace flame graphs, and log ↔ span correlation — four additional axes on top of the v1.14 telemetry mock foundation.</p><h2 id="what-shipped" tabindex="-1">What shipped <a class="header-anchor" href="#what-shipped" aria-label="Permalink to &quot;What shipped&quot;">​</a></h2><ul><li><strong><code>@kiwa/observability</code> v2.0</strong> (major bump) — 4 additional axes over the v1.1 telemetry mock (v1.14-4 land). Zero breaking changes to v1.0 (<code>renderDashboard</code> / <code>detectFlaky</code> / <code>analyzeSpecCoverage</code> / <code>checkThresholds</code>) or v1.1 (<code>TelemetryCollector</code> + <code>createOtelMock</code> / <code>createDatadogMock</code> / <code>createSentryMock</code>) surfaces; the major bump signals the &quot;Observability v2&quot; milestone with 11 new public exports + 13 fixture builders. <ul><li><code>DashboardMock</code> + <code>buildDashboardMock</code> — bind a dashboard to a <code>TelemetryCollector</code>, evaluate N panel queries (<code>sum</code> / <code>avg</code> / <code>max</code> / <code>min</code> / <code>count</code> / <code>last</code>) with optional tag filter + time window, attach <code>PanelThreshold[]</code> for <code>ok</code> / <code>warn</code> / <code>critical</code> badge selection. <code>refresh()</code> returns <code>PanelResult[]</code> and increments <code>refreshCount</code>; <code>panel(id)</code> looks up by id from the most recent results.</li><li><code>AlertRouter</code> — register <code>AlertRule[]</code> against a <code>TelemetryCollector</code>; <code>evaluate()</code> transitions <code>pending → firing</code> under a <code>forSamples</code> gate and resolves back when the metric drops. <code>setRoute</code> walks a nested <code>RouteEntry</code> tree (deepest match wins). <code>addSilence</code> suppresses fires while the label match holds and <code>expiresAt</code> is in the future. <code>setEscalation</code> + <code>tickEscalation()</code> walks a state machine so kiwa tests can assert &quot;reached tier 2 at t=15min&quot; without any wall clock.</li><li><code>buildSpanTree</code> + <code>renderFlameGraph</code> + <code>drillDown</code> + <code>flattenFlame</code> — pure transforms over <code>SpanRecord[]</code> (v1.1 shape unchanged) that reconstruct the span parent chain, compute <code>totalMs</code> / <code>selfMs</code>, collapse siblings by name into <code>FlameNode</code> (samples counted), and extract a subtree with depth normalized to 0. Orphan spans (parent not found) become roots.</li><li><code>LogCorrelationIndex</code> + <code>correlateLogsAndSpans</code> — build a bidirectional index from <code>LogRecord[]</code> and <code>SpanRecord[]</code>; look up <code>logsForSpan</code> / <code>logsForTrace</code> / <code>spansForTrace</code> / <code>linkAll</code>. Configurable <code>CorrelationKeys</code> (<code>traceIdKey</code> / <code>spanIdKey</code> / <code>altTraceIdKeys</code>) covers OpenTelemetry (<code>trace_id</code> / <code>span_id</code>) + Datadog (<code>dd.trace_id</code> / <code>dd.span_id</code>) + Sentry (<code>sentry-trace</code>) conventions.</li><li>Fixture builders — <code>panel_httpErrorRate</code> / <code>panel_p99Latency</code> / <code>panel_queueDepth</code>, <code>rule_errorRateCritical</code> / <code>rule_latencyDegraded</code> / <code>rule_queueBackpressure</code>, <code>defaultRoute</code> / <code>escalation_pagerDutyTwoStep</code> / <code>silence_maintenanceWindow</code>, <code>trace_httpHandler</code> / <code>trace_fanoutParallel</code> / <code>trace_nestedRetry</code>, <code>logs_forHttpTrace</code>. 40+ new behavior tests (67 added, 145 total pass).</li></ul></li><li><strong><code>examples/dogfood-observability-dashboard</code></strong> — Next.js App Router style Grafana dashboard driven behind a provider-neutral <code>DashboardAdapter</code>. 5 canonical panels (line / bar / gauge / stat / table) — 1 per <code>chart_type</code>, backed by a shared PromQL-style query builder module; <code>line</code> and <code>bar</code> both map to the observability package&#39;s <code>timeseries</code> PanelKind, and the app-level <code>chart_type</code> is preserved on <code>PanelRenderResult.chartType</code> so a real <code>app/dashboard/page.tsx</code> server component can pick the correct chart component. <code>makeMockAdapter</code> seeds a <code>TelemetryCollector</code> with 4 metric names (<code>http.errors</code> / <code>http.p99.latency.ms</code> / <code>queue.depth</code> / <code>http.requests</code>) and drives a <code>DashboardMock</code>; <code>makeRealAdapter</code> talks to a Prometheus instant-query endpoint (<code>GET /api/v1/query</code>) when <code>PROMETHEUS_URL</code> is set. 22 vitest tests (18 e2e mock + 3 fidelity + 1 emit) + 2 perf specs. 7-axis release gate verdict PASS.</li><li><strong><code>examples/dogfood-alert-orchestrator</code></strong> — Node.js style Prometheus AlertManager orchestrator behind a provider-neutral <code>AlertOrchestratorAdapter</code>. 10 canonical alert rules (4 threshold + 3 rate + 3 anomaly). Rate + anomaly kinds compile down to threshold checks in the mock adapter (rate divides cumulative counters by elapsed window; anomaly compares latest sample to trailing mean + <code>stddevMult × stddev</code>). 3-level routing tree (<code>severity → team → channel</code>) with 6 leaves so every seeded rule has a distinct receiver. Silence store with literal + regex label matching (regex compilation cached per silence). Escalation ladder L1 30s → L2 5min → L3 30min mirrors PagerDuty&#39;s 3-tier policy. <code>makeRealAdapter</code> POSTs fires to AlertManager <code>/api/v2/alerts</code> when <code>ALERTMANAGER_URL</code> is set. 27 vitest tests + 2 perf specs. 7-axis release gate verdict PASS.</li><li><strong><code>examples/dogfood-trace-flame-graph</code></strong> — React-style trace flame graph explorer behind a provider-neutral <code>FlameExplorerAdapter</code>. 10 canonical trace fixtures (100 spans + 34 logs) across flat HTTP handler / fanout-parallel workers / 3-level nested retry / 6-level React SSR / batched DB write / chunked upload stream / API gateway fan-out / async event bus / cache miss + fill cycle / long-running background job with heartbeats + checkpoints. 5 pure-TS components (<code>FlameGraph</code> / <code>SpanTree</code> / <code>LogPanel</code> / <code>Drilldown</code> / <code>TraceLogIndex</code>) usable directly from a browser SPA render path without DOM dependency. <code>makeMockAdapter</code> uses a memoised per-<code>traceId</code> cache so second-call latency measures Map lookup rather than tree rebuild. <code>makeRealAdapter</code> GETs Jaeger <code>/api/traces/{id}</code> when <code>JAEGER_URL</code> is set. 29 vitest tests + 2 perf specs. 7-axis release gate verdict PASS.</li><li><strong>docs</strong> — 3 new tutorials (22 Observability dashboard / 23 Alert orchestrator / 24 Trace flame graph) + additive migration guide v1.16 → v1.17 + concept doc <code>observability-v2-testing.md</code> documenting the <strong>4 additional axes × 6 semantic axes</strong> (panel query resolution / threshold badge / routing tree / silence + escalation / span aggregate / log ↔ span correlation) as the SSOT. VitePress sidebar refreshed; gh-pages published via <code>/docs-publish-kiwa</code>.</li></ul><h2 id="numbers" tabindex="-1">Numbers <a class="header-anchor" href="#numbers" aria-label="Permalink to &quot;Numbers&quot;">​</a></h2><ul><li><strong>6 sub-Issues resolved</strong> (#778-#783)</li><li><strong>6 PRs merged</strong> (#784-#788 + this publish PR)</li><li><strong>1 major version bump</strong> (<code>@kiwa/observability</code> v1.2 → v2.0.0)</li><li><strong>3 new dogfood apps</strong> with fidelity reports feeding the 7-axis release gate</li><li><strong>40+ new behavior tests</strong> in the harness + <strong>78 dogfood tests</strong> (22 + 27 + 29) all pass</li></ul><h2 id="_7-milestone-streak" tabindex="-1">7-milestone streak <a class="header-anchor" href="#_7-milestone-streak" aria-label="Permalink to &quot;7-milestone streak&quot;">​</a></h2><p>v1.11 (release gate) → v1.12 (non-determinism) → v1.13 (time-axis) → v1.14 (horizontal expansion) → v1.15 (AI-LLM depth) → v1.16 (component depth) → <strong>v1.17 (Observability v2)</strong>. Every milestone since v1.11 has landed 6 sub-Issues in full.</p><h2 id="v2-0-candidates" tabindex="-1">v2.0 candidates <a class="header-anchor" href="#v2-0-candidates" aria-label="Permalink to &quot;v2.0 candidates&quot;">​</a></h2><ul><li>Multi-version Vitest matrix (Vitest 1.x vs 2.x vs 3.x parity)</li><li>Desktop (Electron / Tauri) + mobile (React Native / Expo) adapters</li><li>Framework depth (SolidJS / Fresh / HonoJS)</li><li>Coverage 100% milestone</li><li>Blockchain depth (Reth Rust Ethereum execution client + Foundry-rs 深化 + dApp e2e 拡張)</li><li>Cache / Data depth (Dragonfly / Materialize / Neon)</li></ul><p>Feedback welcome on which of these should land next.</p>',11)])])}const m=o(r,[["render",c]]);export{u as __pageData,m as default};
